// Helper function to count vowels in the string
function CountVowels(s: string): int
    requires s != null
    decreases s.Length
{
    var vCount := 0;
    var n := s.Length;
    var i := 0;
    while i < n
        invariant 0 <= i <= n
        invariant vCount >= 0
    {
        if IsVowel(s[i], i == n - 1) {
            vCount := vCount + 1;
        }
        i := i + 1;
    }
    return vCount;
}

// Helper function to determine if a character is a vowel
function IsVowel(c: char, isYAtEnd: bool): bool
    reads c
{
    c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u' || (isYAtEnd && c == 'y')
